gpU(){return"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u0627\u062a"},
gpO(){return"\u0639\u0636\u0648 \u0645\u0646\u0630"},
gpK(){return"\u0627\u0644\u062f\u0648\u0644\u0629"},
gpH(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpF(){return"\u0627\u0644\u0623\u0644\u0628\u0648\u0645 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpW(){return"\u0627\u0644\u0645\u0642\u0637\u0639 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpY(){return"\u0641\u0646\u0627\u0646\u0648\u0646 \u0641\u0631\u064a\u062f\u0648\u0646"},
gpZ(){return"\u0645\u0642\u0627\u0637\u0639 \u0641\u0631\u064a\u062f\u0629"},
gpX(){return"\u0623\u0644\u0628\u0648\u0645\u0627\u062a \u0641\u0631\u064a\u062f\u0629"},
gxK(){return"\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639"},
gxm(){return"\u064a"},
gtl(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gtm(){return"\u064a\u062a\u064a\u062d \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0625\u0636\u0627\u0641\u0629 \u0623\u063a\u0646\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u062a\u0647\u0627 \u0645\u0628\u0627\u0634\u0631\u0629\u064b \u0641\u064a \u062d\u0633\u0627\u0628\u0643 \u0639\u0644\u0649 Last.fm."},
gts(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0640 Last.fm"},
gz9(){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0645\u0646 32 \u062d\u0631\u0641\u064b\u0627."},
gz7(){return"\u062a\u0641\u0648\u064a\u0636 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gz5(){return"\u0641\u0648\u0651\u0636 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u064a \u0635\u0641\u062d\u0629 Last.fm \u0627\u0644\u0645\u0641\u062a\u0648\u062d\u0629 \u0641\u064a \u0627\u0644\u0645\u062a\u0635\u0641\u062d\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0647\u0646\u0627 \u0644\u0644\u062a\u0623\u0643\u064a\u062f."},
gz6(){return"\u0644\u0642\u062f \u0642\u0645\u062a \u0628\u0627\u0644\u062a\u0641\u0648\u064a\u0636"},
